class Solution {
  private static final int[] DX = {1, 1, -1, -1};
  private static final int[] DY = {1, -1, -1, 1};
  private int[][] grid;
  private int n, m;
  private int[] memo;

  private int solve(int i, int j, int d, int turn) {
    int key = ((i * m + j) * 4 + d) * 2 + turn;
    if (memo[key] != 0) return memo[key];
    int next = grid[i][j] == 2 ? 0 : 2;
    int best = 1;
    int ni = i + DX[d], nj = j + DY[d];
    if (ni >= 0 && ni < n && nj >= 0 && nj < m && grid[ni][nj] == next) {
      best = Math.max(best, 1 + solve(ni, nj, d, turn));
    }
    if (turn == 1) {
      int d2 = (d + 1) & 3;
      ni = i + DX[d2];
      nj = j + DY[d2];
      if (ni >= 0 && ni < n && nj >= 0 && nj < m && grid[ni][nj] == next) {
        best = Math.max(best, 1 + solve(ni, nj, d2, 0));
      }
    }
    return memo[key] = best;
  }

  public int lenOfVDiagonal(int[][] grid) {
    this.grid = grid;
    n = grid.length;
    m = grid[0].length;
    memo = new int[n * m * 8];
    int ans = 0;
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < m; j++) {
        if (grid[i][j] != 1) continue;
        ans = Math.max(ans, 1);
        for (int d = 0; d < 4; d++) {
          int ni = i + DX[d], nj = j + DY[d];
          if (ni >= 0 && ni < n && nj >= 0 && nj < m && grid[ni][nj] == 2) {
            ans = Math.max(ans, 1 + solve(ni, nj, d, 1));
          }
        }
      }
    }
    return ans;
  }
}
